window.TIMELINE = {
 "voice": "narrator: ElevenLabs George (JBFqnCBsd6RMkjVDRZzb), cael: ElevenLabs Harry (SOYHLrjzK2X1ezoPC6cr), voice: ElevenLabs Lily (pFZP5JQG7iQjIQuC4Bku) [eleven_v4] (narrator tempo 1.06)",
 "set": "final",
 "total": 336.944,
 "scenes": [
  {
   "n": 0,
   "name": "The Name They Buried",
   "start": 0,
   "end": 14.219,
   "lines": [
    {
     "id": "C00",
     "speaker": "cael",
     "text": "They told me I was born without a name. I wasn't. They buried it.",
     "start": 2.6,
     "end": 7.479
    }
   ],
   "title": [
    7.619,
    13.819
   ]
  },
  {
   "n": 1,
   "name": "The Broken Seal",
   "start": 14.219,
   "end": 83.589,
   "lines": [
    {
     "id": "L01",
     "speaker": "narrator",
     "text": "In the twelfth year after the Crown was broken, Aethelgard was ruled by seven houses, and trusted by none.",
     "start": 16.619,
     "end": 23.322
    },
    {
     "id": "L02",
     "speaker": "narrator",
     "text": "Seven seats around one throne of blood. Seven oaths, sworn on the same stone, each meaning something different.",
     "start": 23.662,
     "end": 31.39
    },
    {
     "id": "L03",
     "speaker": "narrator",
     "text": "Lord Oswyn of Stanhyrst held the High Seat. He had sent men to die, and grown rich on laws that called some blood lesser.",
     "start": 31.73,
     "end": 39.974
    },
    {
     "id": "L04",
     "speaker": "narrator",
     "text": "In the last winter of his rule, he set out to break those laws.",
     "start": 40.314,
     "end": 44.062
    },
    {
     "id": "L05",
     "speaker": "narrator",
     "text": "Six houses set their seals to his reform. The seventh did not: House Sorn, who kept the First-Born on their chains.",
     "start": 44.762,
     "end": 52.849
    },
    {
     "id": "L06",
     "speaker": "narrator",
     "text": "On the night before the vote, the bells of the northern rookery began to ring.",
     "start": 53.189,
     "end": 57.377
    },
    {
     "id": "L07",
     "speaker": "narrator",
     "text": "A First-Born fell upon the capital. And the whole city looked up.",
     "start": 58.277,
     "end": 62.42
    },
    {
     "id": "L08",
     "speaker": "narrator",
     "text": "No one was watching the council chamber, where Oswyn's own captain put a knife in his back.",
     "start": 63.22,
     "end": 68.414
    },
    {
     "id": "L09",
     "speaker": "narrator",
     "text": "By dawn, the histories were written. A reckless lord. A rookery disaster. A wife and an infant son among the dead.",
     "start": 69.314,
     "end": 77.635
    },
    {
     "id": "L10",
     "speaker": "narrator",
     "text": "But one witness lived. And she was carrying the son.",
     "start": 78.435,
     "end": 82.049
    }
   ]
  },
  {
   "n": 2,
   "name": "The Unsworn",
   "start": 83.589,
   "end": 131.983,
   "lines": [
    {
     "id": "L11",
     "speaker": "narrator",
     "text": "Her name was Sive. Fenfolk. A nursemaid sworn to no house, and owed nothing by any law.",
     "start": 84.989,
     "end": 92.324
    },
    {
     "id": "L12",
     "speaker": "narrator",
     "text": "She carried the heir of Stanhyrst through the burning streets, wrapped in a servant's wool.",
     "start": 92.664,
     "end": 97.89
    },
    {
     "id": "L13",
     "speaker": "narrator",
     "text": "At the lower gate, a guard lifted the blanket. Then he looked at the swords coming down the stairs, and opened the gate.",
     "start": 98.23,
     "end": 105.336
    },
    {
     "id": "L14",
     "speaker": "narrator",
     "text": "They killed him for it.",
     "start": 105.936,
     "end": 107.178
    },
    {
     "id": "L15",
     "speaker": "narrator",
     "text": "Four nights north, where the roads give out beneath the fells, stood a poor hold named Ealdholt.",
     "start": 108.178,
     "end": 113.963
    },
    {
     "id": "L16",
     "speaker": "narrator",
     "text": "Its elder, Edda, asked the child's name. Sive said only: one that will get him killed.",
     "start": 114.303,
     "end": 121.41
    },
    {
     "id": "L17",
     "speaker": "narrator",
     "text": "So Edda gave him her father's. Cael. And in the register, beside his parentage, she wrote one word. Unknown.",
     "start": 122.11,
     "end": 130.243
    }
   ]
  },
  {
   "n": 3,
   "name": "A Son of Ealdholt",
   "start": 131.983,
   "end": 164.014,
   "lines": [
    {
     "id": "L18",
     "speaker": "narrator",
     "text": "Twenty-one winters. The heir to the High Seat grew up mending spears, guarding a ford, and waiting outside the doors of greater men.",
     "start": 134.583,
     "end": 143.395
    },
    {
     "id": "L19",
     "speaker": "narrator",
     "text": "His blood did not make him strong. He practised until his hands bled, and learned to read a man before the man knew his own mind.",
     "start": 143.735,
     "end": 151.67
    },
    {
     "id": "L20",
     "speaker": "narrator",
     "text": "Runa, the healer's girl, warned him once. They don't need to beat you, Cael. They only need to decide you may not stand.",
     "start": 152.01,
     "end": 159.983
    },
    {
     "id": "L21",
     "speaker": "narrator",
     "text": "He did not believe her. Not yet.",
     "start": 160.323,
     "end": 162.674
    }
   ]
  },
  {
   "n": 4,
   "name": "The Ford",
   "start": 164.014,
   "end": 192.563,
   "lines": [
    {
     "id": "L22",
     "speaker": "narrator",
     "text": "When House Hildmere laid claim to Ealdholt's ford, the law offered one answer. The King's Gambit. Living pieces, on a living board.",
     "start": 165.614,
     "end": 174.472
    },
    {
     "id": "L23",
     "speaker": "narrator",
     "text": "Cael stood as a Pawn. He gave ground. He let them believe the open file was a mistake.",
     "start": 174.812,
     "end": 180.812
    },
    {
     "id": "L24",
     "speaker": "narrator",
     "text": "And when their champion came through it, he closed the door.",
     "start": 181.412,
     "end": 184.568
    },
    {
     "id": "L25",
     "speaker": "narrator",
     "text": "Ealdholt kept its road. And for once, its banner was spoken of in the south.",
     "start": 185.368,
     "end": 190.223
    }
   ]
  },
  {
   "n": 5,
   "name": "The Muster",
   "start": 192.563,
   "end": 236.564,
   "lines": [
    {
     "id": "L26",
     "speaker": "narrator",
     "text": "At the National Muster, the Seven chose the pieces that would stand for Aethelgard.",
     "start": 194.163,
     "end": 198.723
    },
    {
     "id": "L27",
     "speaker": "narrator",
     "text": "Knight, bishop, rook and queen, all of them born to it. The front rank was for those who were not.",
     "start": 199.063,
     "end": 205.642
    },
    {
     "id": "L28",
     "speaker": "narrator",
     "text": "The clerk read his papers twice. Ward of Ealdholt. Parentage, unknown.",
     "start": 205.982,
     "end": 211.699
    },
    {
     "id": "L29",
     "speaker": "narrator",
     "text": "In the final trial, Cael reached the last rank. Every gallery waited for him to choose the Queen.",
     "start": 212.499,
     "end": 218.687
    },
    {
     "id": "L30",
     "speaker": "narrator",
     "text": "He chose the Knight. It struck the king and the queen in one move, and the game was over.",
     "start": 219.387,
     "end": 224.907
    },
    {
     "id": "L31",
     "speaker": "narrator",
     "text": "They knighted him for it. A silver star, on a pawn's cloak.",
     "start": 225.607,
     "end": 229.606
    },
    {
     "id": "L32",
     "speaker": "narrator",
     "text": "And in the high gallery, a hooded man asked for every record of the twelfth year.",
     "start": 229.946,
     "end": 234.624
    }
   ]
  },
  {
   "n": 6,
   "name": "The Road Home",
   "start": 236.564,
   "end": 273.245,
   "lines": [
    {
     "id": "L33",
     "speaker": "narrator",
     "text": "Cael would not wait in the capital. He wanted Edda to see the star.",
     "start": 238.164,
     "end": 242.323
    },
    {
     "id": "L34",
     "speaker": "narrator",
     "text": "He bought her a clasp shaped like an oak leaf. Nothing royal. Just something she would like.",
     "start": 242.663,
     "end": 248.214
    },
    {
     "id": "L35",
     "speaker": "narrator",
     "text": "On the north road, a cart lay overturned. No driver. No horse. Then the arrows.",
     "start": 249.114,
     "end": 255.659
    },
    {
     "id": "L36",
     "speaker": "narrator",
     "text": "The men who came out of the trees wore no colours. They had not come for silver.",
     "start": 256.459,
     "end": 261.25
    },
    {
     "id": "L37",
     "speaker": "narrator",
     "text": "They tore his name from the Muster record. And so that no grave would ever be found, they built a fire, and laid him on an iron grate above it.",
     "start": 261.59,
     "end": 270.329
    },
    {
     "id": "L38",
     "speaker": "narrator",
     "text": "He did not beg.",
     "start": 271.229,
     "end": 272.305
    }
   ]
  },
  {
   "n": 7,
   "name": "The Fire",
   "start": 273.245,
   "end": 310.886,
   "lines": [
    {
     "id": "C01",
     "speaker": "cael",
     "text": "No board. No arbiter. Faces hidden. Is this how the Seven fight?",
     "start": 274.645,
     "end": 280.721
    },
    {
     "id": "C02",
     "speaker": "cael",
     "text": "Turn me over, cowards. This side is done.",
     "start": 281.621,
     "end": 286.707
    },
    {
     "id": "C03",
     "speaker": "cael",
     "text": "Burn the name. Burn the boy. I will come back for both.",
     "start": 287.707,
     "end": 292.015
    },
    {
     "id": "L39",
     "speaker": "narrator",
     "text": "They fed the fire until the laughing stopped.",
     "start": 293.415,
     "end": 296.136
    },
    {
     "id": "L40",
     "speaker": "narrator",
     "text": "Twice now, the kingdom had buried his name. This time, it buried him.",
     "start": 297.336,
     "end": 302.045
    },
    {
     "id": "L41",
     "speaker": "narrator",
     "text": "But some pieces, taken from the board, do not stay in the box.",
     "start": 303.445,
     "end": 307.546
    }
   ]
  },
  {
   "n": 8,
   "name": "The Unreturned",
   "start": 310.886,
   "end": 325.744,
   "lines": [
    {
     "id": "V01",
     "speaker": "voice",
     "text": "You remember.",
     "start": 314.286,
     "end": 315.161
    },
    {
     "id": "C04",
     "speaker": "cael",
     "text": "The fire. I remember the fire.",
     "start": 316.361,
     "end": 319.205
    },
    {
     "id": "V02",
     "speaker": "voice",
     "text": "Then you remember dying. Most do not.",
     "start": 320.205,
     "end": 323.804
    }
   ]
  }
 ],
 "chapter": [
  325.344,
  336.344
 ]
};
